const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const rawTitle = body.title || body.rawTitle || '';
  const rawDescription = body.description || body.rawDescription || '';
  const text = `${rawTitle} ${rawDescription}`.toLowerCase();
  const ticketId = body.id || body.ticketId;

  // 1. Categoría Fallback
  let category = 'other';
  if (/factura|cobro|pago|tarjeta|reembolso|suscripci[oó]n|membres[ií]a|precio|dinero/.test(text)) {
    category = 'billing';
  } else if (/bug|error|servidor|crash|api|cuelga|pantalla|c[oó]digo|500|404|database|bd|base de datos|fallo/.test(text)) {
    category = 'technical';
  } else if (/cuenta|login|password|contrase[nñ]a|sesi[oó]n|perfil|correo|acceso|bloquead[oa]|registro/.test(text)) {
    category = 'account';
  }

  // 2. Prioridad Fallback
  let priority = 'low';
  if (/ca[ií]do|urgente|cr[ií]tico|emergencia|seguridad|producci[oó]n|hack|robo/.test(text)) {
    priority = 'urgent';
  } else if (/error|bug|servidor|500|bloquead[oa]|fallo|imposible|no puedo|cae/.test(text)) {
    priority = 'high';
  } else if (/factura|cobro|pago|reembolso|cambio|actualiz/.test(text)) {
    priority = 'medium';
  }

  // 3. Extracción Dinámica de Tags Fallback
  const potentialTags = ['factura', 'cobro', 'pago', 'reembolso', 'bug', 'error', 'servidor', 'cuenta', 'login', 'password', 'urgente', 'crítico', 'android', 'ios', 'api', 'email', '500', '404'];
  const tags = potentialTags.filter(tag => text.includes(tag));
  if (tags.length === 0) tags.push('general');

  // 4. Respuesta Sugerida Fallback
  let suggestedReply = 'Hola, hemos recibido tu solicitud y nuestro equipo de soporte la está revisando. Nos pondremos en contacto contigo a la brevedad.';
  if (category === 'billing') {
    suggestedReply = 'Hola, lamentamos el inconveniente con tu cobro o factura. Estamos revisando los detalles de la transacción para resolverlo cuanto antes.';
  } else if (category === 'technical') {
    suggestedReply = 'Hola, gracias por reportar este error técnico. Nuestro equipo de ingeniería ya ha sido notificado para investigar el origen del problema.';
  } else if (category === 'account') {
    suggestedReply = 'Hola, entendemos que tienes problemas con tu cuenta o acceso. Por seguridad, te guiaremos paso a paso para restablecer tu sesión de forma segura.';
  }

  if (priority === 'urgent') {
    suggestedReply = '¡Atención URGENTE! Hemos priorizado tu caso debido a la criticidad reportada. Un especialista senior se encuentra atendiendo esta incidencia ahora mismo.';
  }

  // Construir Payload Limpio para la API de Gemini
  const promptText = `Analyze this support ticket and classify it into JSON format.\n\nTitle: ${rawTitle}\nDescription: ${rawDescription}\n\nOutput STRICTLY valid JSON with key names:\n- priority: one of ['low', 'medium', 'high', 'urgent']\n- category: one of ['billing', 'technical', 'account', 'other']\n- tags: list of keyword strings\n- suggestedReply: polite customer support response string in Spanish`;

  results.push({
    json: {
      ticketId: Number(ticketId),
      rawTitle,
      rawDescription,
      fallbackPriority: priority,
      fallbackCategory: category,
      fallbackTags: tags,
      fallbackSuggestedReply: suggestedReply,
      geminiPayload: {
        contents: [
          {
            parts: [
              {
                text: promptText
              }
            ]
          }
        ],
        generationConfig: {
          responseMimeType: "application/json"
        }
      }
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const geminiOutput = items[i].json;

  let prepData = {};
  try {
    prepData = $('Rule Fallback Prep').item.json;
  } catch (e) {
    prepData = {};
  }

  let priority = prepData.fallbackPriority || 'medium';
  let category = prepData.fallbackCategory || 'other';
  let tags = prepData.fallbackTags || ['general'];
  let suggestedReply = prepData.fallbackSuggestedReply || 'Hemos recibido tu consulta y la estamos procesando.';

  try {
    if (geminiOutput.candidates && geminiOutput.candidates[0] && geminiOutput.candidates[0].content && geminiOutput.candidates[0].content.parts[0].text) {
      const rawText = geminiOutput.candidates[0].content.parts[0].text;
      const aiData = JSON.parse(rawText);
      if (aiData.priority) priority = aiData.priority;
      if (aiData.category) category = aiData.category;
      if (Array.isArray(aiData.tags) && aiData.tags.length > 0) tags = aiData.tags;
      if (aiData.suggestedReply) suggestedReply = aiData.suggestedReply;
    }
  } catch (e) {
    // Si falla el parseo de la IA, se conservan los valores por regla
  }

  results.push({
    json: {
      ticketId: Number(prepData.ticketId),
      priority,
      category,
      tags,
      suggestedReply,
      enrichmentStatus: 'done'
    }
  });
}

return results;
